package com.tradingsimulator.core;
import com.tradingsimulator.marketdata.adapters.MarketAdapter; import com.tradingsimulator.model.*; import com.tradingsimulator.tradingengine.*; import com.tradingsimulator.tradingengine.botstrategies.IBotStrategy; import com.tradingsimulator.validationandportfolio.*; import java.math.BigDecimal;
public final class TradingFacade { private final ExchangeEngine engine; private final ValidationChain validation=ValidationChain.defaultChain(); private MarketAdapter adapter; private IBotStrategy strategy; private boolean botEnabled;
 public TradingFacade(ExchangeEngine e){engine=e;} public void setMarketAdapter(MarketAdapter a){adapter=a;} public void updateQuote(Quote q){engine.updateQuote(q);} public void refreshQuote(String s){if(adapter==null)throw new IllegalArgumentException("Market adapter is not configured"); updateQuote(adapter.getQuote(s));}
 public Trade submitMarketOrder(String s,OrderSide side,int qty){Quote q=engine.quotes().get(s); if(q==null)throw new IllegalArgumentException("No quote for symbol: "+s); validation.validate(new Order(s,side,OrderType.MARKET,qty,null),engine.cash(),engine.position(s).quantity(),side==OrderSide.BUY?q.ask():q.bid()); return engine.execute(new Order(s,side,OrderType.MARKET,qty,null));}
 public Trade submit(Order o){Quote q=engine.quotes().get(o.symbol());if(q==null)throw new IllegalArgumentException("No quote for symbol: "+o.symbol());validation.validate(o,engine.cash(),engine.position(o.symbol()).quantity(),o.side()==OrderSide.BUY?q.ask():q.bid());return engine.execute(o);} public BigDecimal cash(){return engine.cash();} public Position position(String s){return engine.position(s);} public PortfolioMemento snapshot(){return new PortfolioMemento(engine.cash(),engine.positions(),engine.trades(),engine.quotes());} public void restore(PortfolioMemento m){engine.restore(m.cash(),m.positions(),m.trades(),m.quotes());} public void setStrategy(IBotStrategy s){strategy=s;} public OrderSide strategySignal(java.util.List<BigDecimal> prices){if(strategy==null)throw new IllegalArgumentException("Strategy is not configured");return strategy.signal(prices);} public void setBotEnabled(boolean x){botEnabled=x;} public boolean isBotEnabled(){return botEnabled;}
}
